package com.tattantat.app.data.remote.account
import com.tattantat.app.data.remote.auth.ApiEnvelope
import retrofit2.http.*
interface AccountApi { @GET("me") suspend fun me():ApiEnvelope<AccountPayload>; @PATCH("me") suspend fun updateProfile(@Body r:UpdateProfileRequest):ApiEnvelope<AccountPayload>; @POST("me/push-devices") suspend fun registerPushDevice(@Body r:PushDeviceRequest):ApiEnvelope<PushDevicePayload>; @POST("reports") suspend fun report(@Body r:ReportRequest):ApiEnvelope<ReportPayload>; @POST("users/{id}/block") suspend fun blockUser(@Path("id") id:String):ApiEnvelope<BlockPayload>; @GET("me/blocks") suspend fun blocks():ApiEnvelope<List<BlockedUserPayload>>; @DELETE("users/{id}/block") suspend fun unblockUser(@Path("id") id:String):ApiEnvelope<Unit>; @GET("notifications") suspend fun notifications():ApiEnvelope<List<NotificationPayload>>; @PATCH("notifications/{id}/read") suspend fun readNotification(@Path("id") id:String):ApiEnvelope<NotificationReadPayload>; @PATCH("notifications/read-all") suspend fun readAllNotifications():ApiEnvelope<ReadAllNotificationsPayload>; @GET("seller/reviews") suspend fun sellerReviews():ApiEnvelope<List<SellerReviewPayload>>; @GET("seller/wallet") suspend fun wallet():ApiEnvelope<WalletPayload>; @GET("seller/revenue") suspend fun revenue():ApiEnvelope<SellerRevenuePayload>; @GET("seller/payouts") suspend fun payouts():ApiEnvelope<List<SellerPayoutPayload>>; @GET("seller/bank-accounts") suspend fun bankAccounts():ApiEnvelope<List<BankAccountPayload>>; @POST("seller/bank-accounts") suspend fun addBankAccount(@Body r:CreateBankAccountRequest):ApiEnvelope<BankAccountPayload>; @POST("seller/payout") suspend fun requestPayout(@Header("Idempotency-Key") k:String,@Body r:PayoutRequest):ApiEnvelope<PayoutPayload>; @POST("seller/payouts/{id}/cancel") suspend fun cancelPayout(@Path("id") id:String,@Header("Idempotency-Key") k:String,@Body r:CancelPayoutRequest):ApiEnvelope<SellerPayoutPayload> }
data class AccountPayload(val id:String,val full_name:String,val email:String?,val phone:String?,val avatar_url:String?,val role:String="USER")
data class UpdateProfileRequest(val fullName:String?=null,val avatarUrl:String?=null)
data class NotificationPayload(val id:String,val type:String,val title:String,val content:String,val reference_type:String?,val reference_id:String?,val is_read:Boolean,val created_at:String,val read_at:String?)
data class NotificationReadPayload(val id:String,val is_read:Boolean,val read_at:String?);data class ReadAllNotificationsPayload(val updated:Int);data class WalletPayload(val pendingBalance:String,val availableBalance:String,val heldBalance:String,val currency:String);data class SellerRevenuePayload(val grossSellerPayout:String,val refundedSellerPayout:String,val withdrawn:String,val wallet:WalletPayload,val currency:String);data class BankAccountPayload(val id:String,val bankName:String,val accountHolder:String,val accountNumberMasked:String,val isDefault:Boolean);data class CreateBankAccountRequest(val bankName:String,val accountHolder:String,val accountNumber:String,val isDefault:Boolean=false);data class PayoutRequest(val amount:String,val bankAccountId:String?=null);data class PayoutPayload(val id:String,val amount:String,val netAmount:String,val status:String);data class SellerPayoutPayload(val id:String,val sellerId:String,val amount:String,val fee:String,val netAmount:String,val bankAccountId:String?,val status:String,val requestedAt:String,val processedAt:String?,val failureReason:String?,val currency:String);data class SellerReviewPayload(val id:String,val order_id:String,val rating:Int,val comment:String?,val created_at:String,val buyer_name:String,val average_rating:String);data class PushDeviceRequest(val token:String,val platform:String="ANDROID");data class PushDevicePayload(val id:String,val platform:String,val last_seen_at:String);data class ReportRequest(val productId:String?=null,val reportedUserId:String?=null,val reason:String,val details:String?=null);data class ReportPayload(val id:String,val status:String);data class BlockPayload(val blockedUserId:String);data class BlockedUserPayload(val id:String,val full_name:String,val avatar_url:String?,val created_at:String);data class CancelPayoutRequest(val reason:String?=null)
